    total_a = total_a + sum(dV_best_AA((1 : waypoint_ni) + waypoint_ni * (i - 1)) * v_star - dV_max_allowable_AA_w < 0) %[output:8118a45c] %[output:7d7ad24d] %[output:6fca6ab5] %[output:9efb810c] %[output:23749661] %[output:51377e27] %[output:4fb971c6] %[output:365087e2] %[output:907d2d89]
